fn node_0000() -> NodeDescriptor {
    let mut d = NodeDescriptor::new(
        NodeKind::new("generated.github-rest.actions.add-custom-labels-to-self-hosted-runner-for-org"),
        1,
        "Add custom labels to a self-hosted runner for an organization",
    );
    d.hints.side_effect = SideEffect::NonIdempotent;
    d.description = Some("Adds custom labels to a self-hosted runner configured in an organization.\n\nAuthenticated users must have admin access to the organization to use this endpoint.\n\nOAuth tokens and personal access tokens (classic) need the `admin:org` scope to use this endpoint.".into());
    d.params = ParameterSchema { fields: vec![
        ParameterField::new("org", "Org", ParameterKind::String).required().expression(),
        ParameterField::new("runner_id", "Runner Id", ParameterKind::Number).required().expression(),
        ParameterField::new("body", "Body", ParameterKind::Json).required().expression(),
    ] };
    d
}

